-- GENERATED by generate_copart.py — do not edit by hand.
-- Loads one converted Copart sales CSV (copart_to_csv.py) into copart.sales.
-- Called by load.sh with:
--   -v filename=<csv basename> -v asof=<YYYY-MM-DD> -v source=<xlsx basename>
--   -v sha=<sha256 of the xlsx> -v rows=<data row count>
-- HEADER: vin|lot_nbr|year|make|model|physical_location|location_state|first_auction_date|sale_date|sales_status|runs_at_auction|total_bids|acv|proquote|reserve_amount_on_final_auction|gross_sale_price|total_advance_charges|total_copart_charges|total_seller_charges|net_sale_proceeds
\set ON_ERROR_STOP on
BEGIN;

CREATE TEMP TABLE src (
  vin text,                          -- XLSX: vin
  lot_nbr text,                      -- XLSX: lot_nbr
  year text,                         -- XLSX: year
  make text,                         -- XLSX: make
  model text,                        -- XLSX: model
  physical_location text,            -- XLSX: physical_location
  location_state text,               -- XLSX: location_state
  first_auction_date text,           -- XLSX: first_auction_date
  sale_date text,                    -- XLSX: sale_date
  sales_status text,                 -- XLSX: sales_status
  runs_at_auction text,              -- XLSX: runs_at_auction
  total_bids text,                   -- XLSX: total_bids
  acv text,                          -- XLSX: acv
  proquote text,                     -- XLSX: proquote
  reserve_amount_on_final_auction text, -- XLSX: reserve_amount_on_final_auction
  gross_sale_price text,             -- XLSX: gross_sale_price
  total_advance_charges text,        -- XLSX: total_advance_charges
  total_copart_charges text,         -- XLSX: total_copart_charges
  total_seller_charges text,         -- XLSX: total_seller_charges
  net_sale_proceeds text             -- XLSX: net_sale_proceeds
) ON COMMIT DROP;

-- the CSV is piped in on psql's stdin by load.sh (\copy does not interpolate variables)
\copy src FROM pstdin WITH (FORMAT csv, DELIMITER '|', NULL '', HEADER true, ENCODING 'UTF8')

DELETE FROM copart.report_file WHERE filename = :'filename';
INSERT INTO copart.report_file (report_type, asof_date, filename, source_file, sha256, row_count)
VALUES ('sales', :'asof'::date, :'filename', nullif(:'source', ''), nullif(:'sha', ''), :'rows'::int)
RETURNING file_id \gset

INSERT INTO copart.sales (file_id, asof_date, vin, lot_nbr, year, make, model, physical_location, location_state, first_auction_date, sale_date, sales_status, runs_at_auction, total_bids, acv, proquote, reserve_amount_on_final_auction, gross_sale_price, total_advance_charges, total_copart_charges, total_seller_charges, net_sale_proceeds)
SELECT :file_id, :'asof'::date,
  vervent.parse_text(vin),
  vervent.parse_num(lot_nbr)::bigint,
  vervent.parse_num(year)::smallint,
  vervent.parse_text(make),
  vervent.parse_text(model),
  vervent.parse_text(physical_location),
  vervent.parse_text(location_state),
  vervent.parse_date(first_auction_date),
  vervent.parse_date(sale_date),
  vervent.parse_text(sales_status),
  vervent.parse_num(runs_at_auction)::smallint,
  vervent.parse_num(total_bids)::integer,
  vervent.parse_num(acv),
  vervent.parse_num(proquote),
  vervent.parse_num(reserve_amount_on_final_auction),
  vervent.parse_num(gross_sale_price),
  vervent.parse_num(total_advance_charges),
  vervent.parse_num(total_copart_charges),
  vervent.parse_num(total_seller_charges),
  vervent.parse_num(net_sale_proceeds)
FROM src
ON CONFLICT (asof_date, lot_nbr) DO UPDATE SET
  file_id = EXCLUDED.file_id,
  vin = EXCLUDED.vin,
  year = EXCLUDED.year,
  make = EXCLUDED.make,
  model = EXCLUDED.model,
  physical_location = EXCLUDED.physical_location,
  location_state = EXCLUDED.location_state,
  first_auction_date = EXCLUDED.first_auction_date,
  sale_date = EXCLUDED.sale_date,
  sales_status = EXCLUDED.sales_status,
  runs_at_auction = EXCLUDED.runs_at_auction,
  total_bids = EXCLUDED.total_bids,
  acv = EXCLUDED.acv,
  proquote = EXCLUDED.proquote,
  reserve_amount_on_final_auction = EXCLUDED.reserve_amount_on_final_auction,
  gross_sale_price = EXCLUDED.gross_sale_price,
  total_advance_charges = EXCLUDED.total_advance_charges,
  total_copart_charges = EXCLUDED.total_copart_charges,
